export function MasterDetail({
  title = "{{title}}",
  layout = "{{layout}}",
  masterWidth = {{masterWidth}},
  accent = "{{accent}}",
}) {
  const stacked = layout === "stacked";
  const items = ["Invoice #1042", "Invoice #1041", "Invoice #1040", "Invoice #1039"];
  return (
    <div style={{ display: "flex", flexDirection: stacked ? "column" : "row", height: stacked ? "auto" : 160, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", border: "1px solid #24143022" }}>
      <ul style={{
        flex: "none", boxSizing: "border-box", margin: 0, padding: 0, listStyle: "none", background: "#FAF7F2",
        width: stacked ? "100%" : masterWidth, display: stacked ? "flex" : "block",
        overflowX: stacked ? "auto" : "visible", overflowY: stacked ? "visible" : "auto",
        borderRight: stacked ? "none" : "1px solid #24143018", borderBottom: stacked ? "1px solid #24143018" : "none",
      }}>
        {items.map((label, i) => (
          <li key={label} style={{ padding: "10px 12px", borderBottom: "1px solid #24143012", whiteSpace: "nowrap", background: i === 0 ? accent : "transparent", fontWeight: i === 0 ? 700 : 400 }}>{label}</li>
        ))}
      </ul>
      <div style={{ flex: 1, padding: 14, background: "#fff" }}>
        <h4 style={{ margin: "0 0 8px" }}>{title}</h4>
        <p style={{ margin: 0, color: "#241430cc" }}>Billed to Acme Ltd, due in 14 days.</p>
      </div>
    </div>
  );
}
